$ErrorActionPreference='Stop'
$j=Join-Path $env:TEMP ('smiot-plc-readback-' + [guid]::NewGuid().ToString('N') + '.json')
$py='import json,time,uuid,paho.mqtt.client as mqtt; c=mqtt.Client(); c.connect("localhost",1883,30); c.loop_start(); cid="readback-"+uuid.uuid4().hex; p={"action":"SET_OUTPUTS","farm_key":"greenhouse_a","command_id":cid,"bit0":0,"bit1":0,"synthetic":True,"source":"readback_check"}; c.publish("farm/control",json.dumps(p),qos=1).wait_for_publish(5); print(json.dumps({"command_id":cid})); time.sleep(4); c.loop_stop(); c.disconnect()'
$cmds=@('set -e','cd /opt/smiot',"/opt/smiot/.venv/bin/python -c '$py'")
(@{commands=$cmds}|ConvertTo-Json -Compress)|Set-Content -Encoding ascii $j
$id=(aws ssm send-command --profile aws-moi --region ap-southeast-2 --instance-ids i-00bf2d3591d3ee0a2 --document-name AWS-RunShellScript --parameters file://$j --comment 'SMIOT virtual PLC readback verifier check' --query Command.CommandId --output text).Trim(); do {Start-Sleep 3;$r=aws ssm get-command-invocation --profile aws-moi --region ap-southeast-2 --command-id $id --instance-id i-00bf2d3591d3ee0a2 --output json|ConvertFrom-Json;if($r.Status -in @('Success','Failed','Cancelled','TimedOut')){Write-Output $r.StandardOutputContent;if($r.Status -ne 'Success'){Write-Output $r.StandardErrorContent};break}}while($true); Remove-Item $j -Force -ErrorAction SilentlyContinue
